import{z as A,x as d,o as n,c as p,q as i,j as l,D as e,d as o,s as r,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"连续对离散视觉 token","description":"","frontmatter":{"title":"连续对离散视觉 token","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continuous-vs-discrete-vision-tokens.md","filePath":"llm/continuous-vs-discrete-vision-tokens.md","lastUpdated":1791063341000}'),B={name:"llm/continuous-vs-discrete-vision-tokens.md"};function D(m,a,u,h,c,f){const s=d("Mermaid");return n(),p("div",null,[a[2]||(a[2]=i('<h1 id="连续对离散视觉-token" tabindex="-1">连续对离散视觉 token <a class="header-anchor" href="#连续对离散视觉-token" aria-label="Permalink to &quot;连续对离散视觉 token&quot;">​</a></h1><div class="epigraph"><p>理解型 VLM 多用连续 patch 投影进 LLM；生成型系统常用离散码接自回归，或连续潜变量接扩散。接口选错，后半段再强也补不回。</p><footer>—— 对照 LLaVA 连续视觉 token 与 VQ / 潜空间扩散两条生成路</footer></div><p><a href="/llm/fsq-lfq">上一课</a>用固定网格或无查找编码避免码本崩溃；词表是设计量，ID 邻域不等于语义邻域。缺口是任务轴：绑定与 OCR 对连续早融合友好，似然生成对离散友好，高保真采样对连续扩散友好。主干 <a href="/llm/llava-projector">LLaVA 投影器</a> 走连续 ViT 隐状态；前三课把离散量化写清。本课把选择收成这一轴。不重讲 FSQ 的量化格。后课原生分辨率 ViT 默认已经读完：连续 token 的个数随分辨率涨。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续：ViT 输出 \\(H_v\\in\\mathbb{R}^{N\\times d}\\)，线性或 MLP 投进 LLM 词嵌入空间，梯度从语言损失直达视觉编码器。无码本崩溃，细字靠 \\(N\\) 与分辨率。不能在视觉维上做标准 softmax 词表，生成图像要另接扩散头或连续回归。</p><p>离散：下标序列，LLM 可以统一词表生成图与文，但量化丢信息，文档与定位吃亏。混合系统（理解连续、生成离散）要两套视觉前缀，训练更复杂，后课 Janus / Show-o 再写。</p><p><span class="marginnote">「连续视觉 token」递给语言模型的是一串浮点向量，像把照片切成小块后直接递「色块本身」；「离散 token」递的是码本编号，像把每块颜色归到最近的色卡格子、只报格子号。前者信息全但难当词来生成，后者好生成但有损。</span></p><p><span class="marginnote">「视觉 token」一词在文献里混用。写报告时声明是连续向量还是码本 ID。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>理解 / 对话 / OCR：连续 + 早融合，见融合课。像素级生成：离散 AR 或潜空间扩散（后一单元）。统一模型必须显式选：共享词表、双头、或 Transfusion 式混合目标。评测不要用图文检索余弦去选对话 VLM 的离散码本。</p>',10)),(n(),l(E,null,{default:e(()=>[r(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIX%5B%22%E5%83%8F%E7%B4%A0%22%5D%20--%3E%20C%5B%22%E8%BF%9E%E7%BB%AD%20patch%20%E5%90%91%E9%87%8F%22%5D%0A%20%20PIX%20--%3E%20D%5B%22%E7%A6%BB%E6%95%A3%E7%A0%81%20ID%22%5D%0A%20%20C%20--%3E%20VLM%5B%22%E5%AF%B9%E8%AF%9D%20%2F%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20D%20--%3E%20AR%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E7%94%9F%E6%88%90%22%5D%0A%20%20C%20--%3E%20DIFF%5B%22%E6%89%A9%E6%95%A3%20%2F%20%E6%B5%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"语言损失对连续 \\(H_v\\) 提供稠密梯度，对离散 ID 只提供词表上的交叉熵，中间的解码器是另一套参数。因此理解任务微调 ViT 很有效，微调 VQ 编码器对问答帮助有限——瓶颈在码。生成任务相反：没有离散词表就没有统一的 next-token 目标。",-1)),a[5]||(a[5]=t("p",null,"两条路的梯度通不通，画出来就清楚了：",-1)),(n(),l(E,null,{default:e(()=>[r(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20CONT%5B%22%E8%BF%9E%E7%BB%AD%20patch%22%5D%0A%20%20%20%20L1%5B%22%E8%AF%AD%E8%A8%80%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%7C%22%E7%A8%A0%E5%AF%86%E6%A2%AF%E5%BA%A6%22%7C%20H%5B%22H_v%20%E5%90%91%E9%87%8F%22%5D%20--%3E%20V1%5B%22ViT%20%E7%BC%96%E7%A0%81%E5%99%A8%E8%B7%9F%E7%9D%80%E5%8F%98%E5%BC%BA%22%5D%0A%20%20end%0A%20%20subgraph%20DISC%5B%22%E7%A6%BB%E6%95%A3%20ID%22%5D%0A%20%20%20%20L2%5B%22%E8%AF%AD%E8%A8%80%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20X%5B%22%E8%AF%8D%E8%A1%A8%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%20--%3E%20C2%5B%22%E7%A0%81%E6%9C%AC%E4%B9%8B%E5%A4%96%E6%94%B6%E4%B8%8D%E5%88%B0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">码本可以想象成 256 色的色卡：任何真彩色照片都得先归到这 256 格之一，归完原色就丢了。格子越少越像「写字」、越好生成，但细节损失越大——这就是「量化丢信息」的直观含义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定唯一赢家。下一课在连续路上补分辨率：固定 224 画布是理解侧的第一瓶颈。</p><p><span class="marginnote">为什么「接口选错补不回」：若做文档 OCR 却选了离散码，细字在量化那一步就糊了，后面的语言模型再大，也读不回压根没被存下的信息。选接口先问「这任务丢得起什么信息」，再谈模型规模。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续视觉 token 服务绑定与 OCR；离散码服务统一似然生成。</li><li>梯度路径不同，微调对象不同。</li><li>名词必须声明连续还是 ID。</li><li>出处：LLaVA 连续投影；VQGAN / LDM 生成接口。</li></ul>',6))])}const V=A(B,[["render",D]]);export{_ as __pageData,V as default};
